import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {RoomEnvironment} from './vendor/RoomEnvironment.js';
import {MeshoptDecoder} from './vendor/meshopt_decoder.js';
import {createRouting} from './routing-view.js';

const $=s=>document.querySelector(s),colors={signal:0x61dab8,audio:0xbaa3f7,power:0xf4b961,ground:0x81949b};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={selected:null,net:null,explode:0,wires:true,labels:false,isolate:false};
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(34,1,.05,800);
const canvas=$('#viewport');
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});}catch(error){$('#loading').textContent='3D rendering needs WebGL. Enable hardware acceleration in your browser and reload.';throw error;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setClearColor(0,0);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.78;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.shadowMap.autoUpdate=false;canvas.append(renderer.domElement);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.09;controls.minDistance=18;controls.maxDistance=200;controls.enablePan=true;
const pmrem=new THREE.PMREMGenerator(renderer);const room=new RoomEnvironment();scene.environment=pmrem.fromScene(room,.035).texture;room.dispose();pmrem.dispose();scene.environmentIntensity=.7;
scene.add(new THREE.AmbientLight(0xffffff,.28));
const key=new THREE.DirectionalLight(0xfff6e7,2.4);key.position.set(-35,65,20);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-35,right:35,top:35,bottom:-35,near:1,far:180});key.shadow.bias=-.0002;key.shadow.normalBias=.035;scene.add(key);
const fill=new THREE.DirectionalLight(0xdce8ff,1.5);fill.position.set(35,20,-35);scene.add(fill);const back=new THREE.DirectionalLight(0xf5f1e8,2);back.position.set(-10,-45,30);scene.add(back);
const assembly=new THREE.Group();scene.add(assembly);const overlay=new THREE.Group();scene.add(overlay);
const selectionBox=new THREE.Box3Helper(new THREE.Box3(),0x79e8c2);selectionBox.visible=false;scene.add(selectionBox);
const parts=new Map(),pickables=[];let catalog={},assetInfo={},model;
const routing=createRouting({scene,parts,camera,escape,onSelect:ref=>select(ref),onFrame:frameEndpoints});
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let down;
// Subtle surface variation for solder mask and plated connector housings.
function grain(stripes=false){const a=new Uint8Array(256*256*4);let seed=731;for(let y=0;y<256;y++)for(let x=0;x<256;x++){seed=(1664525*seed+1013904223)>>>0;const v=Math.round(175+(seed/4294967296-.5)*55+(stripes?Math.sin(y*2.7)*24:0)),i=(y*256+x)*4;a[i]=a[i+1]=a[i+2]=v;a[i+3]=255;}const t=new THREE.DataTexture(a,256,256);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(stripes?4:18,stripes?28:18);t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;t.generateMipmaps=true;t.needsUpdate=true;return t;}
const metalGrain=grain(true),pcbGrain=grain();
function finishSurface(mesh,material){if(material.name.startsWith('PCB ')){material.bumpMap=pcbGrain;material.bumpScale=.006;material.map.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());}else if(material.metalness>.5){if(!mesh.geometry.attributes.uv){const p=mesh.geometry.attributes.position,uv=new Float32Array(p.count*2);for(let i=0;i<p.count;i++){uv[i*2]=p.getX(i)*.13;uv[i*2+1]=(p.getY(i)+p.getZ(i))*.13;}mesh.geometry.setAttribute('uv',new THREE.BufferAttribute(uv,2));}material.roughnessMap=metalGrain;material.bumpMap=metalGrain;material.bumpScale=.0015;}material.envMapIntensity=1;material.needsUpdate=true;}

function category(ref){if(/^U[123]$/.test(ref))return 'Processor & memory';if(/^J|^SH/.test(ref))return 'Connectors & shielding';if(/^U|^B/.test(ref))return 'Controllers & power';if(/^SW|^LED/.test(ref))return 'Buttons & indicators';if(/^R/.test(ref))return 'Resistors';if(/^C/.test(ref))return 'Capacitors';if(/^L|^FB|^FL|^X/.test(ref))return 'Inductors, filters & crystals';return 'Diodes & transistors';}
function title(ref){return catalog[ref]?.name||ref;}
function clearOverlay(){for(const child of [...overlay.children]){child.geometry?.dispose();child.material?.map?.dispose();child.material?.dispose();overlay.remove(child);}}
function center(ref){const part=parts.get(ref);return part?new THREE.Box3().setFromObject(part).getCenter(new THREE.Vector3()):null;}
function drawOverlay(){clearOverlay();selectionBox.visible=!!state.selected;
 if(!state.selected)return;const selected=parts.get(state.selected);if(!selected){selectionBox.visible=false;return;}
 selected.updateWorldMatrix(true,true);selectionBox.box.setFromObject(selected).expandByScalar(.22);
 const start=center(state.selected),side=start.y>=0?1:-1;
 routing.draw();
 if(state.labels){const c=document.createElement('canvas');c.width=640;c.height=100;const ctx=c.getContext('2d');ctx.fillStyle='#101b20ed';ctx.roundRect(0,0,640,100,16);ctx.fill();ctx.font='28px Arial';ctx.textAlign='center';ctx.fillStyle='#d9f7eb';ctx.fillText(`${state.selected} · ${title(state.selected).slice(0,35)}`,320,61);const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;const label=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,depthTest:false}));label.position.copy(start);label.position.y+=side*4;label.scale.set(12,1.875,1);overlay.add(label);}
}
function renderIndex(){const q=$('#search').value.toLowerCase(),all=[...new Set([...parts.keys(),...Object.keys(catalog)])],refs=all.filter(ref=>`${ref} ${title(ref)} ${catalog[ref]?.mpn||''} ${catalog[ref]?.description||''}`.toLowerCase().includes(q)).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
 const groups=['Processor & memory','Connectors & shielding','Controllers & power','Buttons & indicators','Resistors','Capacitors','Inductors, filters & crystals','Diodes & transistors'].filter(c=>refs.some(r=>category(r)===c));$('#component-list').innerHTML=refs.length?groups.map((group,index)=>`<details class="part-group" ${q||index<3?'open':''}><summary>${group}<span>${refs.filter(r=>category(r)===group).length}</span></summary>${refs.filter(r=>category(r)===group).map(ref=>`<button class="part ${ref===state.selected?'active':''}" data-ref="${ref}" title="${escape(title(ref))}"><span class="ref">${ref}</span><span>${escape(title(ref))}${parts.has(ref)?'':' · BOM only'}</span></button>`).join('')}</details>`).join(''):'<p class="empty">No matching components.</p>';
 $('#count').textContent=all.length;$('#match-count').textContent=q?`${refs.length} matches`:'';
 for(const button of document.querySelectorAll('.part'))button.onclick=()=>select(button.dataset.ref,true);
}
function overview(){return `<div class="detail-kicker">THE COMPLETE ASSEMBLY</div><h2>BeaglePlay.</h2><p class="description">Explore the board from every angle. Select any component to inspect its identity, physical package, and available electrical connections.</p><div class="overview-specs"><div><strong>4 × A53</strong><span>TI AM6254 processor</span></div><div><strong>2 GB / 16 GB</strong><span>DDR4 memory / eMMC storage</span></div><div><strong>80 × 80 mm</strong><span>PCB footprint</span></div></div><div class="hint-card"><b>See beneath the surface</b><p>Use Back to reveal the processor and radio modules. Explode lifts components away from the PCB.</p></div>`;}
function renderDetails(){if(!state.selected){$('#details').innerHTML=overview();$('#part-number').textContent='';return;}const ref=state.selected,data=catalog[ref]||{},p=parts.get(ref);if(!p){$('#part-number').textContent=ref;$('#details').innerHTML=`<div class="detail-kicker">BILL OF MATERIALS</div><h2>${escape(title(ref))}</h2><div class="model">${escape(data.mpn)}</div><p class="description">${escape(data.description)}</p><div class="hint-card"><b>Geometry not available</b><p>This BOM entry has no matching solid in the source CAD revision. Its position and wires are not inferred.</p></div><div class="resource-links">${data.datasheet?`<a href="${data.datasheet}" target="_blank" rel="noreferrer">Datasheet PDF ↗</a>`:''}${data.mouser?`<a href="${data.mouser}" target="_blank" rel="noreferrer">Find at Mouser ↗</a><a href="${data.digikey}" target="_blank" rel="noreferrer">Find at DigiKey ↗</a>`:''}</div>`;return;}const bounds=new THREE.Box3().setFromObject(p),size=bounds.getSize(new THREE.Vector3()).multiplyScalar(2);
 $('#part-number').textContent=ref;
 $('#details').innerHTML=`<div class="detail-kicker">${p.userData.side==='bottom'?'BACK':'FRONT'} OF BOARD</div><h2>${escape(title(ref))}</h2><div class="model">${escape(data.mpn||'Package in source CAD')}</div><div class="badge">${escape(data.manufacturer||'BeaglePlay assembly')}</div><p class="description">${escape(data.description||'This package is included in the official CAD assembly. A matching entry was not found in the published bill of materials.')}</p><div class="package-size">PACKAGE ENVELOPE <span>${size.x.toFixed(1)} × ${size.z.toFixed(1)} × ${size.y.toFixed(1)} mm</span></div><div class="part-actions"><button id="focus-part">Focus part</button><button id="isolate-part" aria-pressed="${state.isolate}">${state.isolate?'Show assembly':'Isolate part'}</button></div><div class="resource-links">${data.datasheet?`<a target="_blank" rel="noreferrer" href="${data.datasheet}">Datasheet <span>PDF ↗</span></a>`:''}${data.mouser?`<a target="_blank" rel="noreferrer" href="${data.mouser}">Find at Mouser <span>↗</span></a><a target="_blank" rel="noreferrer" href="${data.digikey}">Find at DigiKey <span>↗</span></a>`:'<p class="muted">No confirmed orderable part number in the source BOM.</p>'}</div>${data.mpn&&!data.datasheet?'<p class="muted">No verified direct datasheet link. Distributor search results may include the manufacturer’s document.</p>':''}<section id="pin-panel"></section>`;
 $('#focus-part').onclick=()=>focusPart(ref);$('#isolate-part').onclick=()=>{state.isolate=!state.isolate;applyVisibility();renderDetails();};
 routing.renderPanel();
}
function applyVisibility(){for(const [ref,group] of parts)group.visible=!state.isolate||ref===state.selected;for(const child of assembly.children)if(!child.userData.ref)child.visible=!state.isolate;renderer.shadowMap.needsUpdate=true;drawOverlay();}
function select(ref,turn=false){state.selected=ref;state.net=null;routing.select(ref);state.isolate=false;applyVisibility();renderIndex();renderDetails();$('#inspector').scrollTop=0;
 if(turn){const p=parts.get(ref);if(p&&((p.userData.side==='bottom')!==(camera.position.y<0)))setView(p.userData.side==='bottom'?'back':'front');}
 drawOverlay();$('#clear-selection').hidden=!ref;
}
function focusPart(ref){const p=parts.get(ref),box=new THREE.Box3().setFromObject(p),size=box.getSize(new THREE.Vector3()).length();const target=box.getCenter(new THREE.Vector3());const direction=camera.position.clone().sub(controls.target).normalize();controls.target.copy(target);camera.position.copy(target).addScaledVector(direction,Math.max(14,size*3));controls.update();}
function setView(view){controls.target.set(0,0,0);const distance=Math.max(view==='studio'?74:78,(view==='studio'?96:78)/Math.max(camera.aspect,.3));if(view==='front')camera.position.set(0,distance,.01);else if(view==='back')camera.position.set(0,-distance,.01);else camera.position.set(.8,1.25,1).normalize().multiplyScalar(distance);controls.update();$('#view-label').textContent=view==='studio'?'STUDIO VIEW':view.toUpperCase()+' VIEW';for(const b of document.querySelectorAll('[data-view]'))b.classList.toggle('active',b.dataset.view===view);}
function explode(amount){state.explode=amount;for(const group of parts.values()){group.position.copy(group.userData.base);group.position.y+=(group.userData.side==='bottom'?-1:1)*amount*(7+group.userData.level*1.5);}assembly.updateMatrixWorld(true);renderer.shadowMap.needsUpdate=true;drawOverlay();$('#explode-value').textContent=`${Math.round(amount*100)}%`;}
function isVisible(object){for(let p=object;p;p=p.parent)if(!p.visible)return false;return true;}
function hit(event){const r=canvas.getBoundingClientRect();pointer.set((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);const pin=routing.hit(raycaster);if(pin)return pin;const h=raycaster.intersectObjects(pickables,false).find(h=>isVisible(h.object));return h?.object.userData.ref? h.object.userData.ref:null;}
renderer.domElement.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];});renderer.domElement.addEventListener('pointerup',e=>{if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])<5){const ref=hit(e);if(ref){if(typeof ref==='object')routing.choose(ref);else select(ref);}}down=null;});renderer.domElement.addEventListener('pointermove',e=>{if(e.buttons)return;const ref=hit(e),tip=$('#tooltip'),r=canvas.getBoundingClientRect();tip.hidden=!ref;renderer.domElement.style.cursor=ref?'pointer':'grab';if(ref){tip.textContent=typeof ref==='object'?routing.describe(ref):`${ref} · ${title(ref)}`;tip.style.left=Math.max(4,Math.min(e.clientX-r.left+14,r.width-240))+'px';tip.style.top=Math.max(4,e.clientY-r.top-42)+'px';}});renderer.domElement.addEventListener('pointerleave',()=>$('#tooltip').hidden=true);
$('#search').oninput=renderIndex;$('#clear-selection').onclick=()=>select(null);$('#explode').oninput=e=>explode(Number(e.target.value));$('#connections').onchange=e=>{state.wires=e.target.checked;routing.setEnabled(state.wires);drawOverlay();};$('#labels').onchange=e=>{state.labels=e.target.checked;drawOverlay();};
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>setView(b.dataset.view);
$('#reset').onclick=()=>{state.isolate=false;$('#search').value='';select(null);$('#explode').value=0;explode(0);setView('studio');};
for(const [id,factor] of [['zoom-in',.8],['zoom-out',1.25]])$('#'+id).onclick=()=>{const dir=camera.position.clone().sub(controls.target);dir.setLength(THREE.MathUtils.clamp(dir.length()*factor,controls.minDistance,controls.maxDistance));camera.position.copy(controls.target).add(dir);};
new ResizeObserver(()=>{const r=canvas.getBoundingClientRect(),oldAspect=camera.aspect;renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();if(!state.selected)setView('studio');else{const direction=camera.position.clone().sub(controls.target);direction.setLength(Math.max(direction.length()*Math.max(1,1/camera.aspect)/Math.max(1,1/oldAspect),96/Math.max(camera.aspect,.3)));camera.position.copy(controls.target).add(direction);controls.update();}}).observe(canvas);

async function load(){const began=performance.now();const slow=setTimeout(()=>{const el=$('#loading');if(el)el.innerHTML='<b>The model is taking longer than expected.</b><p>Check your connection, then try again.</p><button onclick="location.reload()">Reload model</button>';},20000);try{
 [catalog,assetInfo]=await Promise.all(['bom.json','assembly.json'].map(name=>fetch(new URL('./assets/'+name,import.meta.url)).then(r=>{if(!r.ok)throw new Error(`Cannot load ${name}`);return r.json();})));
 const loader=new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);const gltf=await loader.loadAsync(new URL('./assets/beagleplay.glb',import.meta.url).href,event=>{const progress=$('#loading-progress');if(progress&&event.total)progress.textContent=`${Math.round(event.loaded/event.total*100)}%`;});model=gltf.scene;
 for(const child of [...model.children]){assembly.add(child);if(child.userData.ref){child.userData.base=child.position.clone();child.userData.level=parts.size%4;parts.set(child.userData.ref,child);}child.traverse(mesh=>{if(mesh.isMesh){mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.ref=child.userData.ref||null;pickables.push(mesh);for(const material of Array.isArray(mesh.material)?mesh.material:[mesh.material])finishSurface(mesh,material);}});}
 renderer.shadowMap.needsUpdate=true;renderIndex();renderDetails();setView('studio');renderer.render(scene,camera);clearTimeout(slow);$('#loading')?.remove();canvas.dataset.loadMs=Math.round(performance.now()-began);canvas.dataset.pageReadyMs=Math.round(performance.now());canvas.dataset.ready='true';$('#cad-status').textContent=`${parts.size} components · Official CAD`;
 }catch(error){clearTimeout(slow);$('#loading').innerHTML=`<b>The model could not be loaded.</b><p>${escape(error.message)}</p><button onclick="location.reload()">Try again</button>`;console.error(error);}}
load();renderer.setAnimationLoop(()=>{controls.update();routing.updateLabels();renderer.render(scene,camera);});

function frameEndpoints(start,end){
 const target=new THREE.Vector3((start.x+(end?.x??start.x))/2,0,(start.z+(end?.z??start.z))/2);
 const span=Math.max(Math.abs(start.x-(end?.x??start.x))/Math.max(camera.aspect,.3),Math.abs(start.z-(end?.z??start.z)),10);
 controls.target.copy(target);camera.position.copy(target).add(new THREE.Vector3(0,Math.max(65,(span+18)/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))) ,.01));controls.update();
 $('#view-label').textContent='PIN-TO-PIN · X-RAY';for(const b of document.querySelectorAll('[data-view]'))b.classList.remove('active');
}
